import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const exitTimer = setTimeout(() => setIsExiting(true), 3500);
    const finish = setTimeout(onComplete, 4500);
    return () => { clearTimeout(exitTimer); clearTimeout(finish); };
  }, [onComplete]);

  // The Apple "Pro" Ease
  const smoothEase = [0.16, 1, 0.3, 1];

  return (
    <div className="h-screen w-full bg-[#FFF24D] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE AMBIENT LIGHT (The "Magic" Glow) */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 0.4, scale: 1.5 }}
        transition={{ duration: 3, ease: "easeOut" }}
        className="absolute inset-0 light-leak pointer-events-none"
      />

      {/* 2. THE CORE UNIT */}
      <motion.div 
        animate={isExiting ? { scale: 15, opacity: 0, filter: "blur(40px)" } : { scale: 1 }}
        transition={{ duration: 1, ease: smoothEase }}
        className="flex flex-col items-center z-10"
      >
        <div className="flex items-center justify-center animate-merge">
          {/* THE BEET RED T2T */}
          <motion.h1 
            initial={{ x: -100, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            transition={{ duration: 1.2, ease: smoothEase }}
            className="text-[12rem] md:text-[18rem] font-[1000] italic text-[#AB1717] leading-none select-none"
          >
            T
          </motion.h1>

          <motion.div 
            initial={{ scale: 0, rotate: -45 }}
            animate={{ scale: 1, rotate: 12 }}
            transition={{ delay: 0.4, duration: 1, type: "spring", bounce: 0.4 }}
            className="mx-[-10px] md:mx-[-25px] relative"
          >
            <div className="bg-[#AB1717] w-24 h-24 md:w-40 md:h-40 flex items-center justify-center shadow-[0_20px_50px_rgba(171,23,23,0.4)]">
               <span className="text-white text-7xl md:text-[10rem] font-black italic">2</span>
            </div>
          </motion.div>

          <motion.h1 
            initial={{ x: 100, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            transition={{ duration: 1.2, ease: smoothEase, delay: 0.1 }}
            className="text-[12rem] md:text-[18rem] font-[1000] italic text-[#AB1717] leading-none select-none"
          >
            T
          </motion.h1>
        </div>

        {/* THE GRASSY GREEN WORKER TAG */}
        <motion.div 
          initial={{ width: 0, opacity: 0 }}
          animate={{ width: "auto", opacity: 1 }}
          transition={{ delay: 1.2, duration: 0.8, ease: smoothEase }}
          className="overflow-hidden mt-[-30px] md:mt-[-50px]"
        >
          <div className="bg-[#47510B] px-10 py-2 transform skew-x-[-12deg]">
            <span className="text-[#FFF24D] font-[1000] text-2xl md:text-4xl uppercase italic tracking-[0.3em] whitespace-nowrap">
              Worker
            </span>
          </div>
        </motion.div>
      </motion.div>

      {/* 3. THE LENIN BLUE ACCENTS (Minimalist Data) */}
      <div className="absolute bottom-12 w-full px-16 flex justify-between items-end overflow-hidden">
        <motion.div 
          initial={{ y: 20 }}
          animate={{ y: 0 }}
          transition={{ delay: 1.5 }}
          className="flex flex-col gap-1"
        >
          <div className="h-[2px] w-8 bg-[#003366]" />
          <span className="font-mono text-[10px] text-[#003366] font-black uppercase opacity-40">
            Secure_Node_Active
          </span>
        </motion.div>

        <motion.span 
          initial={{ opacity: 0 }}
          animate={{ opacity: 0.15 }}
          transition={{ delay: 2 }}
          className="text-[#003366] font-black text-8xl italic absolute right-[-20px] bottom-[-20px] pointer-events-none"
        >
          04
        </motion.span>
      </div>
    </div>
  );
};

export default WorkerSplash;
